    purpose: str
    frame_in_menu: int
    frame_out_menu: int
    observation_date: date
    """The date of the non-NAD 83 side; the NAD 83 side is 2010-01-01."""

    stdin: str
    raw_sha256: str
    records: tuple[NearTieRecord, ...]


